import {useCallback,useEffect,useRef,useState,type FormEvent,type ReactNode} from 'react';
import {Activity,ArrowDownToLine,ArrowLeft,ArrowRight,Check,CheckCircle2,ChevronRight,Cloud,Cog,Globe,HeartPulse,Info,KeyRound,LayoutDashboard,LoaderCircle,LogOut,Menu,Network,Pause,Play,Plus,RefreshCw,Search,Server,Settings2,ShieldCheck,ShieldOff,SlidersHorizontal,Terminal,Trash2,TriangleAlert,X,Zap} from 'lucide-react';
import {api,ApiError,json} from './api';
import {blankProfile,isPublicIPv4,parseVless,validateProfile} from './profile';
import {loadSubscription,type SubscriptionServer} from './subscription';
import type {GuardEvent,Host,Node,Overview,Pool,PoolInput,ProbeProfile,Settings,Target,TargetStatus,Zone} from './types';

import {pageNames,pageFromHash,type Page} from './navigation';
import {TargetDNS} from './TargetDNS';
import {TargetCards} from './TargetCards';
type ModalState={type:'pool';pool?:Pool}|{type:'target';pool:Pool}|{type:'import';pool:Pool}|{type:'profile';pool:Pool}|{type:'confirm';title:string;description:string;label:string;danger?:boolean;action:()=>Promise<unknown>}|null;
type Notice={message:string;error:boolean};
const statusNames:Record<TargetStatus,string>={unknown:'Ожидает проверки',healthy:'Доступен',suspect:'Под подозрением',excluded:'Исключён',recovering:'Восстанавливается',disabled:'Отключён вручную',protected:'Последний A · защищён',stale:'Нет свежих данных'};
function date(value:string|null){return value?new Intl.DateTimeFormat('ru-RU',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date(value)):'Ещё не было';}
function errorMessage(error:unknown){return error instanceof Error?error.message:'Не удалось выполнить действие. Попробуйте ещё раз.';}
function IconButton({children,label,onClick,disabled=false,className=''}:{children:ReactNode;label:string;onClick:()=>void;disabled?:boolean;className?:string}){return <button className={`icon-button ${className}`} title={label} aria-label={label} onClick={onClick} disabled={disabled}>{children}</button>}
function Badge({children,tone='muted'}:{children:ReactNode;tone?:string}){return <span className={`badge ${tone}`}><span className="badge-dot"/>{children}</span>}
function Empty({icon=<Network size={28}/>,title,description,action}:{icon?:ReactNode;title:string;description:string;action?:ReactNode}){return <div className="empty"><div className="empty-icon">{icon}</div><h3>{title}</h3><p>{description}</p>{action}</div>}
function ErrorBox({message}:{message:string}){return <div className="error-box" role="alert"><TriangleAlert size={18}/><span>{message}</span></div>}
function Spinner({label='Загрузка…'}:{label?:string}){return <span className="loading-label"><LoaderCircle className="spin" size={17}/>{label}</span>}
function Field({label,help,children}:{label:string;help?:string;children:ReactNode}){return <label className="field"><span>{label}</span>{children}{help&&<small>{help}</small>}</label>}
function Modal({title,subtitle,children,onClose,busy=false}:{title:string;subtitle?:string;children:ReactNode;onClose:()=>void;busy?:boolean}){
 const dialog=useRef<HTMLDivElement>(null),stateRef=useRef({busy,onClose});stateRef.current={busy,onClose};
 useEffect(()=>{const previous=document.activeElement as HTMLElement|null;const first=dialog.current?.querySelector<HTMLElement>('input:not(:disabled),select:not(:disabled),textarea:not(:disabled),button:not(:disabled)');first?.focus();const handle=(event:KeyboardEvent)=>{if(event.key==='Escape'&&!stateRef.current.busy)stateRef.current.onClose();if(event.key==='Tab'){const all=[...(dialog.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]')||[])];const first=all[0],last=all[all.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}};document.addEventListener('keydown',handle);const old=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{document.removeEventListener('keydown',handle);document.body.style.overflow=old;previous?.focus();};},[]);
 return <div className="modal-backdrop" onMouseDown={event=>{if(event.target===event.currentTarget&&!busy)onClose();}}><div ref={dialog} className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header className="modal-header"><div><h2 id="modal-title">{title}</h2>{subtitle&&<p>{subtitle}</p>}</div><IconButton label="Закрыть" onClick={onClose} disabled={busy}><X size={20}/></IconButton></header>{children}</div></div>;
}

export default function App(){
 const [user,setUser]=useState<string|null>(null),[authLoading,setAuthLoading]=useState(true);
 const [page,setPage]=useState<Page>(()=>pageFromHash(window.location.hash));
 const [mobileOpen,setMobileOpen]=useState(false),[overview,setOverview]=useState<Overview|null>(null),[pools,setPools]=useState<Pool[]>([]),[events,setEvents]=useState<GuardEvent[]>([]),[settings,setSettings]=useState<Settings|null>(null);
 const [selectedId,setSelectedId]=useState<string|null>(null),[targets,setTargets]=useState<Target[]>([]),[targetsLoading,setTargetsLoading]=useState(false);
 const [loading,setLoading]=useState(true),[loadError,setLoadError]=useState(''),[updated,setUpdated]=useState<Date|null>(null),[notice,setNotice]=useState<Notice|null>(null),[modal,setModal]=useState<ModalState>(null),[busyKeys,setBusyKeys]=useState<Set<string>>(new Set());
 const [eventLevel,setEventLevel]=useState(''),[eventType,setEventType]=useState(''),[eventPool,setEventPool]=useState(''),[eventLoading,setEventLoading]=useState(false),[eventError,setEventError]=useState('');
 const selected=pools.find(p=>p.id===selectedId)||null;
 const selectedRef=useRef(selectedId),targetRequest=useRef(0),eventRequest=useRef(0);selectedRef.current=selectedId;
 const handleFailure=useCallback((error:unknown)=>{if(error instanceof ApiError&&error.status===401){setUser(null);setModal(null);}return errorMessage(error);},[]);
 useEffect(()=>{let active=true;api<{username:string}>('/auth/me').then(data=>{if(active)setUser(data.username);}).catch(error=>{if(active&&(!(error instanceof ApiError)||error.status!==401))setLoadError(errorMessage(error));}).finally(()=>{if(active)setAuthLoading(false);});return()=>{active=false;};},[]);
 const load=useCallback(async(quiet=false)=>{if(!quiet)setLoading(true);const results=await Promise.allSettled([api<Overview>('/overview'),api<Pool[]>('/pools'),api<Settings>('/settings')]);let firstError='';if(results[0].status==='fulfilled')setOverview(results[0].value);else firstError=handleFailure(results[0].reason);if(results[1].status==='fulfilled')setPools(results[1].value);else firstError ||=handleFailure(results[1].reason);if(results[2].status==='fulfilled')setSettings(results[2].value);else firstError ||=handleFailure(results[2].reason);setLoadError(firstError);if(!firstError)setUpdated(new Date());setLoading(false);},[handleFailure]);
 const loadTargets=useCallback(async(id:string,quiet=false)=>{const request=++targetRequest.current;if(!quiet)setTargetsLoading(true);try{const data=await api<Target[]>(`/pools/${id}/targets`);if(request===targetRequest.current&&selectedRef.current===id)setTargets(data);}catch(error){if(request===targetRequest.current&&selectedRef.current===id)setNotice({message:handleFailure(error),error:true});}finally{if(request===targetRequest.current&&selectedRef.current===id)setTargetsLoading(false);}},[handleFailure]);
 const loadEvents=useCallback(async(quiet=false)=>{const request=++eventRequest.current;if(!quiet)setEventLoading(true);const query=new URLSearchParams({limit:page==='overview'?'8':'100'});if(page==='events'){if(eventLevel)query.set('level',eventLevel);if(eventType)query.set('type',eventType);if(eventPool)query.set('pool_id',eventPool);}try{const data=await api<GuardEvent[]>(`/events?${query}`);if(request===eventRequest.current){setEvents(data);setEventError('');}}catch(error){if(request===eventRequest.current)setEventError(handleFailure(error));}finally{if(request===eventRequest.current)setEventLoading(false);}},[page,eventLevel,eventType,eventPool,handleFailure]);
 useEffect(()=>{if(user)void load();},[user,load]);
 useEffect(()=>{if(user&&(page==='overview'||page==='events'))void loadEvents();},[user,page,loadEvents]);
 useEffect(()=>{setTargets([]);if(user&&selectedId)void loadTargets(selectedId);},[user,selectedId,loadTargets]);
 useEffect(()=>{if(!user)return;const id=window.setInterval(()=>{if(document.visibilityState!=='visible')return;void load(true);if(selectedId)void loadTargets(selectedId,true);if(page==='overview'||page==='events')void loadEvents(true);},20000);return()=>window.clearInterval(id);},[user,page,selectedId,load,loadTargets,loadEvents]);
 useEffect(()=>{const listener=()=>setPage(pageFromHash(window.location.hash));window.addEventListener('hashchange',listener);return()=>window.removeEventListener('hashchange',listener);},[]);
 const navigate=(value:Page)=>{setPage(value);window.location.hash=value;setMobileOpen(false);};
 const refresh=async()=>{await load();if(selectedId)await loadTargets(selectedId);if(page==='overview'||page==='events')await loadEvents();};
 const refreshAfterError=async()=>{await load(true);if(selectedId)await loadTargets(selectedId,true);};
 const run=async(key:string,action:()=>Promise<unknown>,message:string|((result:unknown)=>string))=>{setBusyKeys(previous=>new Set(previous).add(key));try{const result=await action();setNotice({message:typeof message==='function'?message(result):message,error:false});await load(true);if(selectedId)await loadTargets(selectedId,true);if(page==='overview'||page==='events')await loadEvents(true);}catch(error){setNotice({message:handleFailure(error),error:true});if(!(error instanceof ApiError&&error.status===401))await refreshAfterError();}finally{setBusyKeys(previous=>{const next=new Set(previous);next.delete(key);return next;});}};
 const signOut=async()=>{setBusyKeys(previous=>new Set(previous).add('logout'));try{await api('/auth/logout',json('POST'));setUser(null);setOverview(null);setPools([]);setSelectedId(null);setTargets([]);setEvents([]);setSettings(null);setNotice(null);setLoadError('');setEventLevel('');setEventType('');setEventPool('');}catch(error){setNotice({message:handleFailure(error),error:true});}finally{setBusyKeys(previous=>{const next=new Set(previous);next.delete('logout');return next;});}};
 const openPool=(pool:Pool)=>{setSelectedId(pool.id);navigate('pools');};
 const togglePool=(pool:Pool)=>{if(pool.automation_enabled){void run(pool.id,()=>api(`/pools/${pool.id}`,json('PATCH',{automation_enabled:false})),'Автоматизация приостановлена. Проверки продолжаются.');}else setModal({type:'confirm',title:'Включить автоматизацию?',description:`DNS Guard будет исключать и возвращать A-записи ${pool.hostname} по результатам проверок из РФ. Последняя A-запись останется защищённой. Для запуска нужны профиль и хотя бы один узел.`,label:'Включить автоматизацию',action:()=>api(`/pools/${pool.id}`,json('PATCH',{automation_enabled:true}))});};
 const targetAction=(target:Target,action:'disable'|'delete'|'enable')=>{if(action==='enable'){void run(target.id,()=>api(`/targets/${target.id}/enable`,json('POST')),'Узел включён: A-запись добавлена, мониторинг возобновлён.');return;}setModal({type:'confirm',title:action==='delete'?'Удалить узел из пула?':'Отключить узел вручную?',description:action==='delete'?`Узел ${target.name} (${target.ip}) и его A-запись будут удалены. Последнюю A-запись удалить нельзя.`:`A-запись ${target.ip} будет удалена из DNS. Узел не вернётся автоматически — включите его вручную. Последнюю A-запись отключить нельзя.`,label:action==='delete'?'Удалить узел':'Отключить узел',danger:true,action:()=>api(`/targets/${target.id}${action==='disable'?'/disable':''}`,json(action==='delete'?'DELETE':'POST'))});};
 if(authLoading)return <div className="auth-page"><div className="brand"><ShieldCheck size={30}/><span>DNS<span>Guard</span></span></div><Spinner label="Проверка сессии…"/></div>;
 if(!user)return <Login initialError={loadError} onLogin={username=>{setLoadError('');setUser(username);}}/>;
 return <div className="app-shell">
  {mobileOpen&&<div className="sidebar-shade" onClick={()=>setMobileOpen(false)}/>}
  <aside className={`sidebar ${mobileOpen?'open':''}`}><a className="brand" href="#overview" onClick={()=>navigate('overview')}><div className="brand-mark"><ShieldCheck size={25}/></div><span>DNS<span>Guard</span></span></a><div className="workspace-tag"><span className="tiny-dot"/>Панель управления</div><div className="nav-label">РАБОЧЕЕ ПРОСТРАНСТВО</div><nav aria-label="Основная навигация">{([{id:'overview',icon:LayoutDashboard},{id:'pools',icon:Network},{id:'events',icon:Terminal},{id:'settings',icon:Cog}] as const).map(item=><button key={item.id} className={`nav-item ${page===item.id?'active':''}`} onClick={()=>navigate(item.id)}><item.icon size={19}/><span>{pageNames[item.id]}</span>{item.id==='pools'&&pools.length>0&&<span className="nav-count">{pools.length}</span>}</button>)}</nav><div className="sidebar-bottom"><div className="agent-mini"><div className={`agent-symbol ${overview?.agent_healthy?'online':''}`}><Activity size={19}/></div><div><strong>RU probe agent</strong><span>{overview?.agent_healthy?'Контроль доступен':overview?.agent_last_seen?'Контроль недоступен':'Ожидает подключения'}</span></div><span className={`tiny-dot ${overview?.agent_healthy?'':'off'}`}/></div><button className="user-button" onClick={()=>void signOut()} disabled={busyKeys.has('logout')} title="Выйти из системы"><span className="avatar">{user.slice(0,2).toUpperCase()}</span><span><strong>{user}</strong><small>Администратор</small></span><LogOut size={17}/></button><div className="sidebar-footer">DNS Guard <span>v1.0</span></div></div></aside>
  <main className="main"><header className="topbar"><div className="breadcrumb"><IconButton label="Открыть меню" className="mobile-menu" onClick={()=>setMobileOpen(true)}><Menu size={21}/></IconButton><span>Рабочее пространство</span><ChevronRight size={15}/><strong>{pageNames[page]}</strong></div><div className="topbar-right"><span className="topbar-live"><span className={`tiny-dot ${overview?.agent_healthy?'':'off'}`}/>{overview?.agent_healthy?'Агент подключён':'Агент не готов'}</span><span className="topbar-divider"/><span className="avatar small">{user.slice(0,2).toUpperCase()}</span></div></header>
   <div className="content"><div className="page-heading"><div><div className="eyebrow">{page==='overview'?'МОНИТОРИНГ И АВТОМАТИЗАЦИЯ':page==='pools'?'ИНФРАСТРУКТУРА':page==='events'?'ИСТОРИЯ ОПЕРАЦИЙ':'КОНФИГУРАЦИЯ'}</div><h1>{page==='pools'&&selected?selected.name:pageNames[page]}</h1><p>{page==='overview'?'Доступность узлов из РФ. DNS под контролем.':page==='pools'&&selected?selected.hostname:page==='pools'?'Управляйте A-записями и правилами восстановления.':page==='events'?'Проверки, изменения DNS и действия администратора.':'Подключения сервисов и состояние probe-агента.'}</p></div><div className="heading-actions"><button className="button secondary" onClick={()=>void refresh()} disabled={loading}><RefreshCw size={16} className={loading?'spin':''}/><span>Обновить</span></button>{(page==='overview'||page==='pools'&&!selected)&&<button className="button primary" onClick={()=>setModal({type:'pool'})}><Plus size={17}/>Создать пул</button>}</div></div>
    {notice&&<div className={`notice ${notice.error?'error':'success'}`} role={notice.error?'alert':'status'}>{notice.error?<TriangleAlert size={18}/>:<CheckCircle2 size={18}/>}<span>{notice.message}</span><IconButton label="Закрыть уведомление" onClick={()=>setNotice(null)}><X size={16}/></IconButton></div>}
    {loadError&&<ErrorBox message={loadError}/>}
    {loading&&!overview&&<div className="panel initial-loading"><Spinner label="Загрузка панели…"/></div>}
    {page==='overview'&&<><div className="metric-grid"><Metric label="DNS-пулы" value={overview?.pools} icon={<Network size={20}/>} detail="Общие профили подключения"/><Metric label="Узлы в мониторинге" value={overview?.targets} icon={<Server size={20}/>} detail="Проверки через VLESS"/><Metric label="Доступные узлы" value={overview?.healthy} icon={<HeartPulse size={20}/>} detail="Свежая успешная проверка" tone="green"/><Metric label="Исключены из DNS" value={overview?.excluded} icon={<ShieldOff size={20}/>} detail="Проверки продолжаются" tone="amber"/></div>
     <div className={`agent-banner ${overview?.agent_healthy?'healthy':''}`}><div className="agent-banner-icon"><Activity size={22}/></div><div><h3>{overview?.agent_healthy?'Проверки из России доступны':overview?.agent_last_seen?'Контрольное соединение агента недоступно':'Подключите probe-агент в России'}</h3><p>{overview?.agent_healthy?'Агент проверяет соединения через VLESS. Недоступные узлы остаются под наблюдением.':overview?.agent_last_seen?'Сбой контрольного соединения не считается сбоем узлов. Ожидаем восстановления агента.':'До подключения агента результаты проверок не появятся. Настройте агент и общий профиль пула.'}</p></div><button className="button text" onClick={()=>navigate('settings')}>Состояние агента<ArrowRight size={16}/></button></div>
     <div className="panel"><PanelHeading title="DNS-пулы" description="Один hostname · общий профиль · независимые узлы" action={<button className="button text" onClick={()=>{setSelectedId(null);navigate('pools');}}>Все пулы<ArrowRight size={16}/></button>}/><PoolTable pools={pools} onSelect={openPool} onEdit={pool=>setModal({type:'pool',pool})} onToggle={togglePool} busy={busyKeys} onCreate={()=>setModal({type:'pool'})}/></div>
     <div className="overview-bottom"><div className="panel events-panel"><PanelHeading title="Последние события" action={<button className="button text" onClick={()=>navigate('events')}>Открыть журнал<ArrowRight size={16}/></button>}/>{eventError?<ErrorBox message={eventError}/>:eventLoading&&!events.length?<div className="panel-loading"><Spinner/></div>:<EventList events={events} pools={pools} compact/>}</div><div className="panel integrations-panel"><PanelHeading title="Подключения"/><IntegrationRow name="Cloudflare" detail="Управление A-записями" icon={<Cloud size={22}/>} configured={overview?.cloudflare_configured}/><IntegrationRow name="Remnawave" detail="Импорт узлов и хостов" icon={<Network size={22}/>} configured={overview?.remnawave_configured}/><div className="integration-footer"><div className="info-note"><ShieldCheck size={17}/><p>Последняя A-запись защищена от автоматического и ручного удаления.</p></div><button className="button secondary full" onClick={()=>navigate('settings')}><Settings2 size={16}/>Настроить подключения</button></div></div></div>
    </>}
    {page==='pools'&&(selected?<><button className="back-link" onClick={()=>setSelectedId(null)}><ArrowLeft size={16}/>Все DNS-пулы</button><PoolDetail pool={selected} targets={targets} targetsLoading={targetsLoading} busy={busyKeys} onEdit={()=>setModal({type:'pool',pool:selected})} onProfile={()=>setModal({type:'profile',pool:selected})} onAdd={()=>setModal({type:'target',pool:selected})} onImport={()=>setModal({type:'import',pool:selected})} onToggle={()=>togglePool(selected)} onSync={()=>void run(`${selected.id}-sync`,()=>api<{added:number;message:string}>(`/pools/${selected.id}/sync`,json('POST')),result=>{const data=result as {added:number;message:string};return `${data.message} Добавлено: ${data.added}.`;})} onCheck={()=>void run(`${selected.id}-check`,()=>api(`/pools/${selected.id}/check`,json('POST')),'Проверка поставлена в очередь. Результат появится после следующего опроса агента.')} onTargetAction={targetAction}/></>:<div className="panel"><PanelHeading title="Ваши DNS-пулы" description="Автоматизация включается отдельно для каждого пула"/><PoolTable pools={pools} onSelect={openPool} onEdit={pool=>setModal({type:'pool',pool})} onToggle={togglePool} busy={busyKeys} onCreate={()=>setModal({type:'pool'})}/></div>)}
    {page==='events'&&<div className="panel"><PanelHeading title="Журнал" description="Последние 100 событий по выбранным фильтрам"/><div className="filters"><SlidersHorizontal size={18}/><label className="sr-only" htmlFor="level-filter">Уровень</label><select id="level-filter" value={eventLevel} onChange={e=>setEventLevel(e.target.value)}><option value="">Все уровни</option><option value="info">Информация</option><option value="warning">Предупреждения</option><option value="error">Ошибки</option></select><label className="sr-only" htmlFor="type-filter">Тип события</label><select id="type-filter" value={eventType} onChange={e=>setEventType(e.target.value)}><option value="">Все типы событий</option><option value="check">Проверки</option><option value="dns">DNS</option><option value="manual">Действия пользователя</option><option value="system">Система</option></select><label className="sr-only" htmlFor="pool-filter">Пул</label><select id="pool-filter" value={eventPool} onChange={e=>setEventPool(e.target.value)}><option value="">Все пулы</option>{pools.map(pool=><option key={pool.id} value={pool.id}>{pool.name}</option>)}</select>{(eventLevel||eventType||eventPool)&&<button className="button text" onClick={()=>{setEventLevel('');setEventType('');setEventPool('');}}>Сбросить<X size={14}/></button>}</div>{eventError&&<ErrorBox message={eventError}/>}<div aria-busy={eventLoading}>{eventLoading?<div className="panel-loading"><Spinner label="Загрузка событий…"/></div>:<EventList events={events} pools={pools}/>}</div></div>}
    {page==='settings'&&settings&&<SettingsView settings={settings} onSaved={async message=>{setNotice({message,error:false});await load(true);}} onAuthError={handleFailure}/>}
    <footer className="content-footer"><span><ShieldCheck size={14}/>Последняя A-запись всегда под защитой</span><span>{updated?`Данные обновлены в ${updated.toLocaleTimeString('ru-RU')}`:'Ожидаем данные сервера'}</span></footer>
   </div>
  </main>
  {modal?.type==='pool'&&<PoolForm pool={modal.pool} onClose={()=>setModal(null)} onSaved={async pool=>{setModal(null);setNotice({message:modal.pool?'Настройки пула сохранены.':'Пул создан. Добавьте профиль проверки и узлы.',error:false});await load(true);openPool(pool);}}/>}
  {modal?.type==='target'&&<TargetForm pool={modal.pool} onFailure={refreshAfterError} onClose={()=>setModal(null)} onSaved={async()=>{setModal(null);setNotice({message:'Узел добавлен: A-запись создана или принята под управление.',error:false});await load(true);await loadTargets(modal.pool.id);}}/>}
  {modal?.type==='import'&&<ImportForm pool={modal.pool} onFailure={refreshAfterError} onClose={()=>setModal(null)} onSaved={async()=>{setModal(null);setNotice({message:'Узел Remnawave добавлен в DNS-пул.',error:false});await load(true);await loadTargets(modal.pool.id);}}/>}
  {modal?.type==='profile'&&<ProfileForm pool={modal.pool} onClose={()=>setModal(null)} onSaved={async()=>{setModal(null);setNotice({message:'Общий профиль сохранён. Счётчики последовательных проверок сброшены.',error:false});await load(true);await loadTargets(modal.pool.id);}}/>}
  {modal?.type==='confirm'&&<ConfirmModal data={modal} onFailure={refreshAfterError} onClose={()=>setModal(null)} onDone={async()=>{setModal(null);setNotice({message:'Действие выполнено.',error:false});await load(true);if(selectedId)await loadTargets(selectedId,true);await loadEvents(true);}}/>}
 </div>;
}

function Metric({label,value,icon,detail,tone='blue'}:{label:string;value:number|undefined;icon:ReactNode;detail:string;tone?:string}){return <div className={`metric ${tone}`}><div className="metric-top"><span>{label}</span><div className="metric-icon">{icon}</div></div><div className="metric-value">{value??'—'}</div><div className="metric-detail"><span className="tiny-dot"/>{detail}</div></div>}
